using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CustomEventSetupsList", menuName = "Data/Map/CustomEventSetups List")]
public class CustomEventSetupsList : ScriptableObject
{
	[SerializeField]
	private List<CustomEventSetup> customEventSetups = new List<CustomEventSetup>();

	public List<CustomEventSetup> CustomEventSetups => customEventSetups;

	public CustomEventSetup GetCustomEventSetups(string customEventSetupsName)
	{
		string text = customEventSetupsName.Replace(" ", "").ToLower();
		for (int i = 0; i < customEventSetups.Count; i++)
		{
			if (text == customEventSetups[i].name.ToLower())
			{
				return customEventSetups[i];
			}
		}
		return null;
	}

	public CustomEventSetup GetCustomEventSetupsUsingOnlyEventNameDebug(string customEventSetupsName)
	{
		string value = customEventSetupsName.Replace(" ", "").ToLower();
		for (int i = 0; i < customEventSetups.Count; i++)
		{
			if (!customEventSetups[i].MuteForDebug && customEventSetups[i].name.ToLower().Contains(value))
			{
				return customEventSetups[i];
			}
		}
		return null;
	}
}
